    .stdout(
      format!(
        "{} {} {} {}\n",
        target::arch(),
        target::os(),
        target::family(),
        num_cpus::get()
      )
      .as_str(),
    )
    .stderr(
      format!(
        "echo {} {} {} {}\n",
        target::arch(),
        target::os(),
        target::family(),
